  const [kind,setKind]=useState<'release'|'evidence'>('release'),[subjectId,setSubject]=useState(''),[version,setVersion]=useState(1),[owner,setOwner]=useState(''),[reason,setReason]=useState(''),[evidenceRef,setEvidence]=useState(''),[selectedId,setSelected]=useState('');
