function GovernanceSection({descriptor,state,patientId,patients,busy,onAction}:{descriptor:Descriptor;state:State;patientId?:string;patients:readonly {id:string;name:string}[];busy:boolean;onAction:(action:Action)=>Promise<boolean>}){
  const [selection,setSelection]=useState<{id:string;requestId?:string;created?:boolean}>({id:descriptor.records[0]?.id??''});
  const createdId=createdGovernanceRecordId(state,descriptor.kind,selection.requestId);
  const selectedId=createdId??selection.id;
  const selected=descriptor.records.find((record)=>record.id===selectedId);
  const recordHeading=useRef<HTMLHeadingElement>(null);
  if(createdId)setSelection({id:createdId,created:true});
  const createdSelectionId=selection.created?selection.id:undefined;
  useEffect(()=>{
    if(createdSelectionId)recordHeading.current?.focus();
  },[createdSelectionId]);
  async function saveDraft(action:Action){
    const createsRecord=!('id' in action&&action.id);
    if(createsRecord)setSelection(current=>({id:current.id,requestId:action.requestId}));
    const saved=await onAction(action);
    if(!saved&&createsRecord)setSelection(current=>current.requestId===action.requestId?{id:current.id}:current);
    return saved;
  }
  const reviewRequired=selected?needsCurrentReview(selected,state):false;
  return <Panel title={descriptor.title} subtitle={descriptor.description}><div className={styles.section}><label className={styles.selector}>Select {descriptor.kind} record<select value={selectedId} disabled={busy} onChange={(event)=>setSelection({id:event.target.value})}><option value="">Create new record</option>{descriptor.records.map((record)=><option key={record.id} value={record.id}>{title(record)} · {statuses(record)} · v{record.version}</option>)}</select></label>
    {selected&&<div className={styles.record}><h3 ref={recordHeading} tabIndex={-1}>{title(selected)} · version {selected.version}</h3>{(createdId||selection.created)&&<p role="status">Created and selected {title(selected)}. Choose an action below to continue its review.</p>}<Badge tone={reviewRequired?'rose':statuses(selected)==='approved'||statuses(selected)==='active'||statuses(selected)==='publication-recorded'?'teal':'amber'}>{reviewRequired?'review-required':statuses(selected)}</Badge><p>Record ID: <code>{selected.id}</code></p><p>Updated {formatDate(selected.updatedAt,true)}</p>{reviewRequired&&<p role="status">The recorded status is {statuses(selected)}. Its evidence or configuration is no longer current; a new review is required.</p>}{'sampleNotice' in selected&&<p>{selected.sampleNotice}</p>}{'regulatoryAuthorizationNote' in selected&&<p>{selected.regulatoryAuthorizationNote}</p>}{'bridge' in selected&&selected.bridge.notes.map((note)=><p key={note}>{note}</p>)}<TransitionEditor key={`transition-${selected.id}-${selected.version}`} kind={descriptor.kind} record={selected} state={state} patientId={patientId} patients={patients} busy={busy} onAction={onAction}/>{descriptor.kind==='operation'&&<RecoveryEditor key={`recovery-${selected.id}-${selected.version}`} record={selected as OperationRecord} busy={busy} onAction={onAction}/>}<History record={selected}/>{descriptor.kind==='monitoring'&&(selected as MonitoringRecord).exportRecords.length>0&&<Button type="button" variant="outline" disabled={busy} onClick={()=>exportJson(`monitoring-${selected.id}-reviewed-package.json`,(selected as MonitoringRecord).exportRecords[0])}>Download reviewed monitoring package</Button>}<Button type="button" variant="outline" size="sm" disabled={busy} onClick={()=>exportJson(`governance-${selected.id}.json`,selected)}>Export selected record</Button></div>}
    <details open={!selected}><summary>{selected?'Edit or copy record':'New record details'}</summary><DraftEditor key={`draft-${selected?.id??'new'}-${selected?.version??0}`} descriptor={descriptor} record={selected} state={state} patients={patients} busy={busy} onAction={saveDraft}/></details>
    {!descriptor.records.length?<EmptyState title="No records yet" description="Save a draft, then select it to review, revise, and record transitions."/>:<p>{descriptor.records.length} records available. Select a record to continue its workflow.</p>}
  </div></Panel>;
}

export function ProgramGovernancePanel({patientId,patients,state,patientPathways,busy,onAction}:{patientId?:string;patients:readonly {id:string;name:string}[];state:State;patientPathways?:Context['patientPathways'];busy:boolean;onAction:(action:Action)=>Promise<boolean>}){
  const [notice,setNotice]=useState('');
  const [error,setError]=useState('');
  const [saving,setSaving]=useState(false);
  const [now,setNow]=useState(()=>new Date().toISOString());
  const inFlight=useRef(false);
  useEffect(()=>{const timer=setInterval(()=>setNow(new Date().toISOString()),60000);return()=>clearInterval(timer);},[]);
  const summary=getSummary(state,patientId,now);
  async function submit(action:Action){
    if(inFlight.current||busy)return false;
    inFlight.current=true;setSaving(true);setError('');setNotice('');
    try{const ok=await onAction(action);if(ok)setNotice('Governance record saved.');else setError('The record was not saved. Your draft is retained; review the reported issue and try again.');return ok;}catch(cause){setError(cause instanceof Error?cause.message:'The record was not saved. Your draft is retained.');return false;}finally{inFlight.current=false;setSaving(false);}
  }
  const descriptors:Descriptor[]=[
    {kind:'configuration',journey:'J22',title:'Program configuration',description:'Review capability settings and preserve non-hideable safety essentials.',records:state.configurations,defaults:{title:'',capabilityChoices:['assessments','messages'],allowedCadence:['weekly'],languages:['English'],communicationSettings:['in-app'],displayReferences:[],safetyEssentials:['Visible safety disclaimer','Named reviewer'],nonHideableSafetyEssentials:['Visible safety disclaimer','Named reviewer'],reviewNote:''},fields:[{key:'title',label:'Configuration title'},{key:'capabilityChoices',label:'Capability choices, one per line: assessments, reviewPrompts, digitalTwin, pst, shadow, advisor, pathways, messages',kind:'lines'},{key:'allowedCadence',label:'Allowed cadence, one per line: daily, weekly, monthly, quarterly, manual-only',kind:'lines'},{key:'languages',label:'Languages, one per line',kind:'lines'},{key:'communicationSettings',label:'Communication channels, one per line: in-app, phone, email, interpreter, proxy',kind:'lines'},{key:'displayReferences',label:'Display references, one per line',kind:'lines',required:false},{key:'safetyEssentials',label:'Visible safety essentials, one per line',kind:'lines'},{key:'nonHideableSafetyEssentials',label:'Non-hideable safety essentials, one per line',kind:'lines'},{key:'reviewNote',label:'Draft notes',kind:'textarea',required:false}]},
    {kind:'protocol',journey:'J23',title:'Protocol authoring',description:'Author an operational protocol, resolve questions, record review and publication, then assign a published version.',records:state.protocols,defaults:{title:'',owner:'',evidenceLocator:'',unresolvedQuestions:[],steps:[initialStep()],publicationChecks:emptyChecks()},fields:[{key:'title',label:'Protocol title'},{key:'owner',label:'Protocol owner'},{key:'evidenceLocator',label:'Protocol evidence locator'},{key:'unresolvedQuestions',label:'Unresolved questions, one per line',kind:'lines',required:false}]},
    {kind:'evidence',journey:'J24',title:'Evidence and content registry',description:'Record exact sources, rights, dates, and translations. Evidence changes invalidate dependent reviews.',records:state.evidences,defaults:{title:'',indication:'',population:'',endpoint:'',supportingSources:[initialSource()],rights:'public-summary',rightsExpiry:'',instrumentVersion:'',approvedTranslation:'',reviewNote:''},fields:[{key:'title',label:'Evidence title'},{key:'indication',label:'Indication'},{key:'population',label:'Population'},{key:'endpoint',label:'Endpoint'},{key:'rights',label:'Rights basis',kind:'select',options:['owned','licensed','public-summary']},{key:'rightsExpiry',label:'Rights expiry date (unavailable from this date)',kind:'date',required:false},{key:'instrumentVersion',label:'Instrument version',required:false},{key:'approvedTranslation',label:'Translation approval reference',required:false},{key:'reviewNote',label:'Evidence notes',kind:'textarea',required:false}]},
    {kind:'release',journey:'J25',title:'Release registry',description:'Keep exact release metadata, evaluation, decisions, and observed rollout or rollback records.',records:state.releases,defaults:{title:'',modelId:'',softwareId:'',configurationId:state.activeConfigurationId??'',intendedUse:'',evidenceRefIds:[],modelClaims:[],evaluation:{agreementSummary:'',performanceSummary:'',limitations:''},unresolvedConditions:[],overrideTrainingPolicy:'Manual review only'},fields:[{key:'title',label:'Release title'},{key:'modelId',label:'Model ID'},{key:'softwareId',label:'Software ID'},{key:'configurationId',label:'Active configuration record ID'},{key:'intendedUse',label:'Intended use',kind:'textarea'},{key:'evidenceRefIds',label:'Evidence record IDs, one per line',kind:'lines',required:false},{key:'modelClaims',label:'Model claims, one per line',kind:'lines',required:false},{key:'unresolvedConditions',label:'Unresolved conditions, one per line',kind:'lines',required:false},{key:'overrideTrainingPolicy',label:'Override training policy'}]},
    {kind:'operation',journey:'J26',title:'Operations',description:'Record incident or restore-exercise evidence, owner confirmation, review, and closure.',records:state.operations,defaults:{title:'',kind:'incident',affectedServices:[],owner:'',severity:'medium',actionsTaken:[],evidenceRef:'',restoreOutcome:'not-applicable'},fields:[{key:'title',label:'Operation title'},{key:'kind',label:'Operation kind',kind:'select',options:['incident','restore-proof']},{key:'affectedServices',label:'Affected services, one per line',kind:'lines'},{key:'owner',label:'Operation owner'},{key:'severity',label:'Severity',kind:'select',options:['low','medium','high','critical']},{key:'actionsTaken',label:'Reported actions, one per line',kind:'lines',required:false},{key:'evidenceRef',label:'Operation evidence locator'},{key:'restoreOutcome',label:'Reported restore outcome (use not-applicable for incidents)',kind:'select',options:['not-applicable','reported-success','reported-failure']}]},
    {kind:'monitoring',journey:'J27',title:'Monitoring documentation',description:'Document actual service activity and qualified review. Billing eligibility needs external payer and legal review.',records:state.monitoring,defaults:{serviceDate:now.slice(0,10),activity:'',source:'',evidenceRef:'',missingDocumentation:[],patientId:'',performerId:'',serviceCode:'',intervals:[emptyInterval()],ruleRef:emptyRule()},fields:[{key:'serviceDate',label:'Service date',kind:'date'},{key:'activity',label:'Service activity'},{key:'source',label:'Documentation source'},{key:'evidenceRef',label:'Monitoring evidence locator'},{key:'missingDocumentation',label:'Missing documentation, one per line',kind:'lines',required:false}]},
    {kind:'readiness',journey:'J28',title:'Release readiness',description:'Review claims, partner obligations, required gates, and evidence before recording a readiness decision.',records:state.readiness,defaults:{title:'',functions:[],claims:[],partnerAssets:[],partnerRights:[],partnerResponsibilities:[],evidenceRefIds:[],blockingConditions:[],mandatoryGates:initialGates(),releaseRef:undefined,scope:emptyScope()},fields:[{key:'title',label:'Readiness title'},{key:'functions',label:'Functions, one per line',kind:'lines'},{key:'claims',label:'Claims, one per line',kind:'lines'},{key:'partnerAssets',label:'Partner assets, one per line',kind:'lines',required:false},{key:'partnerRights',label:'Partner rights, one per line',kind:'lines',required:false},{key:'partnerResponsibilities',label:'Partner responsibilities, one per line',kind:'lines',required:false},{key:'evidenceRefIds',label:'Supporting evidence record IDs, one per line',kind:'lines',required:false},{key:'blockingConditions',label:'Blocking conditions, one per line',kind:'lines',required:false}]},
  ];
  const assignment=state.protocolAssignments.find((record)=>record.patientId===patientId);
  const openRecalls=state.recalls.filter(record=>record.status==='open').length;
  const firstReview=descriptors.find(descriptor=>descriptor.records.some(record=>needsCurrentReview(record,state)))?.kind;
  return <div className={styles.panel+' clinical-governance-editor'}><Panel title="Program governance" subtitle="Review program settings, evidence, releases, and ongoing responsibilities."><div className={styles.section}><Badge tone={summary.overdue?'rose':summary.open?'amber':'teal'}>{summary.open} open · {summary.overdue} overdue</Badge><p>Open a registry to review its records. Saved reviews document supplied evidence; they do not deploy or authorize clinical use.</p>{patientId&&<p>Patient context: {patients.find((patient)=>patient.id===patientId)?.name??patientId}{assignment?` · Assigned protocol version ${assignment.protocolVersion}`:''}</p>}{assignment?.protocolSnapshot&&<details><summary>Assigned protocol snapshot</summary><p>{assignment.protocolSnapshot.title} · version {assignment.protocolVersion}</p><ol>{assignment.protocolSnapshot.steps.map((step)=><li key={step.id}>{step.title} · {step.owner}</li>)}</ol></details>}{summary.attention.length>0&&<div className={styles.attention}><strong>Attention</strong><ul>{summary.attention.map((item)=><li key={item}>{item}</li>)}</ul></div>}<div className={styles.actions}><Button variant="outline" size="sm" disabled={busy||saving} onClick={()=>exportJson('program-governance.json',state)}>Export all governance records</Button><Button variant="outline" size="sm" disabled={busy||saving} onClick={()=>exportJson('program-governance-approvals.json',{configurations:state.configurations,releases:state.releases,readiness:state.readiness})}>Export approval-related records</Button></div><p role="status" aria-live="polite">{notice}</p>{error&&<p role="alert" className={styles.error}>{error}</p>}<p className="clinical-proof-note"><strong>External proof still required:</strong> partner and legal approvals, actual deployment or restore verification, payer review, and clinical validation.</p></div></Panel>
    <details className="clinical-workflow-step" open={openRecalls>0}><summary><span>Model and evidence recalls<small>Suspended artifacts and affected patient reviews</small></span><b className={openRecalls?'clinical-attention-count':''}>{openRecalls} open</b></summary><div className="clinical-step-body"><RecallPanel state={state} busy={busy||saving} onAction={submit}/></div></details>
    <details className="clinical-workflow-step"><summary><span>Protocol transitions<small>Review assignments, version changes, and open work</small></span><b>{state.protocolAssignments.length} assignments</b></summary><div className="clinical-step-body"><MigrationPanel state={state} patientPathways={patientPathways} busy={busy||saving} onAction={submit}/></div></details>
    <div className="clinical-registry-list">{descriptors.map(descriptor=>{const needsReview=descriptor.records.filter(record=>needsCurrentReview(record,state)).length;return <details className="clinical-workflow-step" key={descriptor.kind} open={!openRecalls&&descriptor.kind===(firstReview??'configuration')}><summary data-journey={descriptor.journey}><span>{descriptor.title}<small>{descriptor.description}</small></span><b className={needsReview?'clinical-attention-count':''}>{needsReview?needsReview+' need review':descriptor.records.length+' records'}</b></summary><div className="clinical-step-body"><GovernanceSection descriptor={descriptor} state={state} patientId={patientId} patients={patients} busy={busy||saving} onAction={submit}/></div></details>;})}</div>
  </div>;
}
